1	import { useState, useEffect, useCallback, useRef } from 'react';
2	import { supabase } from '@/integrations/supabase/client';
3	import { FinancialTransaction, FinancialTransactionType, Asset, Installment } from '@/types/financial';
4	import { toast } from 'sonner';
5	import { DateRange } from 'react-day-picker';
6	import { format } from 'date-fns';
7	import { todayLocalISO } from '@/utils/dateUtils';
8	import { wideDebug, wideInfo, wideWarn, wideError } from '@/shared/lib/telemetry/wide-events';
9	import { handleError } from '@/shared/lib/error-handler';
10	import { roundMoney } from '@/shared/lib/roundMoney';
11	
12	export interface FinanceiroStore {
13	    id: number;
14	    nome: string;
15	}
16	
17	export interface CostCenter {
18	    id: number;
19	    code: string;
20	    name: string;
21	    active: boolean;
22	}
23	
24	export const useFinancialAccounts = () => {
25	    const [transactions, setTransactions] = useState<FinancialTransaction[]>([]);
26	    const [categories, setCategories] = useState<{ id: number, name: string, nature: string, account_name?: string, group_name?: string, default_account_id?: number | null }[]>([]);
27	    const [costCenters, setCostCenters] = useState<CostCenter[]>([]);
28	    const [finStores, setFinStores] = useState<FinanceiroStore[]>([]);
29	    const [selectedLojaId, setSelectedLojaId] = useState<string>('all');
30	
31	    const fetchCategories = async () => {
32	        try {
33	            const { data, error } = await supabase
34	                .from('finance_mgmt_subaccounts')
35	                .select(`
36	                    id, 
37	                    name, 
38	                    nature,
39	                    default_account_id,
40	                    account:finance_mgmt_accounts (
41	                        name,
42	                        group:finance_mgmt_groups (
43	                            name
44	                        )
45	                    )
46	                `)
47	                .eq('active', true)
48	                .order('name');
49	
50	            if (error) throw error;
51	
52	            const transformed = (data || []).map((item: any) => ({
53	                id: item.id,
54	                name: item.name,
55	                nature: item.nature,
56	                default_account_id: item.default_account_id || null,
57	                account_name: item.account?.name,
58	                group_name: item.account?.group?.name
59	            }));
60	
61	            setCategories(transformed);
62	        } catch (error) {
63	            handleError(error, { domain: 'financeiro', operation: 'fetchCategories', showToast: false });
64	        }
65	    };
66	
67	    const fetchCostCenters = async () => {
68	        try {
69	            const { data, error } = await supabase
70	                .from('finance_cost_centers')
71	                .select('id, code, name, active')
72	                .eq('active', true)
73	                .order('code');
74	            if (error) throw error;
75	            setCostCenters((data || []) as CostCenter[]);
76	        } catch (error) {
77	            handleError(error, { domain: 'financeiro', operation: 'fetchCostCenters', showToast: false });
78	        }
79	    };
80	
81	    const fetchStores = async () => {
82	        try {
83	            const { data, error } = await supabase
84	                .from('lojas')
85	                .select('id, nome')
86	                .eq('ativo', true)
87	                .order('nome');
88	            if (error) throw error;
89	            setFinStores((data as FinanceiroStore[]) || []);
90	        } catch (error) {
91	            handleError(error, { domain: 'financeiro', operation: 'fetchStores', showToast: false });
92	        }
93	    };
94	
95	    useEffect(() => {
96	        fetchCategories();
97	        fetchStores();
98	        fetchCostCenters();
99	    }, []);
100	    const [isLoading, setIsLoading] = useState(true);
101	    const [summary, setSummary] = useState({
102	        totalPayable: 0,
103	        totalReceivable: 0,
104	        totalOverdue: 0,
105	        totalPaidMonth: 0,
106	        totalPaid: 0,
107	        totalReceived: 0,
108	        countPaid: 0,
109	        countReceived: 0,
110	        countPayable: 0,
111	        countReceivable: 0,
112	        countOverdue: 0,
113	        uncategorizedCount: 0,
114	        dateContext: 'Todos os períodos',
115	        // Rich KPIs
116	        totalInterestPaid: 0,
117	        dueSoon7d: 0,
118	        dueSoon7dCount: 0,
119	        netBalance: 0,
120	        avgPaymentDelay: 0,
121	    });
122	
123	    // Pagination & Filter State
124	    const [page, setPage] = useState(1);
125	    const [hasMore, setHasMore] = useState(false);
126	    const [totalCount, setTotalCount] = useState(0);
127	    const pageSize = 100;
128	
129	    // Store last fetch params to allow re-calculating summary after mutations
130	    const lastFetchParams = useRef<{ dateRange?: DateRange, lojaId?: string }>({});
131	
132	    const fetchTransactions = async (
133	        dateRange?: DateRange,
134	        status?: string,
135	        lojaId?: string,
136	        tipo?: string,
137	        sortBy: string = 'data_vencimento',
138	        sortAsc: boolean = false,
139	        search?: string,
140	        categories?: string[],
141	    ) => {
142	        // Update ref with latest params
143	        lastFetchParams.current = { dateRange, lojaId };
144	
145	        setIsLoading(true);
146	        try {
147	            let query = supabase
148	                .from('financial_transactions_unified' as any)
149	                .select('*', { count: 'exact' });
150	
151	            // Apply Store Filter
152	            const effectiveLojaId = lojaId ?? selectedLojaId;
153	            if (effectiveLojaId && effectiveLojaId !== 'all') {
154	                query = query.eq('loja_id', parseInt(effectiveLojaId));
155	            }
156	
157	            // Apply Date Filters
158	            if (dateRange?.from) {
159	                query = query.gte('data_vencimento', format(dateRange.from, 'yyyy-MM-dd'));
160	            }
161	            if (dateRange?.to) {
162	                query = query.lte('data_vencimento', format(dateRange.to, 'yyyy-MM-dd'));
163	            }
164	
165	            // Apply Status Filter
166	            if (status && status !== 'all') {
167	                if (status === 'liquidado') {
168	                    query = query.in('status', ['pago', 'recebido']);
169	                } else {
170	                    query = query.eq('status', status);
171	                }
172	            }
173	
174	            // Apply Tipo Filter
175	            if (tipo && tipo !== 'all') {
176	                query = query.eq('tipo', tipo);
177	            }
178	
179	            // Server-side search (ilike on descricao or beneficiario)
180	            if (search && search.trim()) {
181	                const term = `%${search.trim()}%`;
182	                query = query.or(`descricao.ilike.${term},beneficiario.ilike.${term}`);
183	            }
184	
185	            // Server-side category filter
186	            if (categories && categories.length > 0) {
187	                query = query.in('categoria', categories);
188	            }
189	
190	            // Pagination
191	            const from = (page - 1) * pageSize;
192	            const to = from + pageSize - 1;
193	
194	            query = query
195	                .order(sortBy, { ascending: sortAsc, nullsFirst: false })
196	                .range(from, to);
197	
198	            const { data, error, count } = await query;
199	
200	            if (error) throw error;
201	
202	            const today = todayLocalISO();
203	            const typedData = (data as FinancialTransaction[]).map(t => ({
204	                ...t,
205	                isOverdue: t.status === 'pendente' && !!t.data_vencimento && t.data_vencimento < today,
206	            }));
207	            setTransactions(typedData);
208	            setHasMore((count || 0) > to + 1);
209	            setTotalCount(count || 0);
210	
211	            calculateSummary(dateRange, lojaId);
212	
213	        } catch (error) {
214	            handleError(error, { domain: 'financeiro', operation: 'fetchTransactions', showToast: false });
215	            toast.error('Erro ao carregar contas');
216	        } finally {
217	            setIsLoading(false);
218	        }
219	    };
220	
221	    // Helper: fetch ALL rows from a Supabase query using batch pagination
222	    // Supabase PostgREST limits to 1000 rows per request by default
223	    const fetchAllRows = async (buildQuery: () => any): Promise<any[]> => {
224	        const BATCH = 1000;
225	        let allData: any[] = [];
226	        let from = 0;
227	        while (true) {
228	            const { data: batch } = await buildQuery().range(from, from + BATCH - 1);
229	            if (!batch || batch.length === 0) break;
230	            allData = allData.concat(batch);
231	            if (batch.length < BATCH) break;
232	            from += BATCH;
233	        }
234	        return allData;
235	    };
236	
237	    const calculateSummary = async (dateRange?: DateRange, lojaId?: string) => {
238	        const today = todayLocalISO();
239	        const effectiveLojaId = lojaId ?? selectedLojaId;
240	
241	        // Build date context label
242	        let dateContext = 'Todos os períodos';
243	        if (dateRange?.from && dateRange?.to) {
244	            const fromStr = format(dateRange.from, 'dd/MM/yyyy');
245	            const toStr = format(dateRange.to, 'dd/MM/yyyy');
246	            dateContext = `${fromStr} — ${toStr}`;
247	        } else if (dateRange?.to) {
248	            dateContext = `Até ${format(dateRange.to, 'dd/MM/yyyy')}`;
249	        } else if (dateRange?.from) {
250	            dateContext = `A partir de ${format(dateRange.from, 'dd/MM/yyyy')}`;
251	        }
252	
253	        // Fetch ALL pending/overdue transactions using batch pagination
254	        const buildPendingQuery = () => {
255	            let q = supabase.from('financial_transactions_unified' as any).select('valor, tipo, status, data_vencimento, is_parent, valor_juros');
256	            if (effectiveLojaId && effectiveLojaId !== 'all') {
257	                q = q.eq('loja_id', parseInt(effectiveLojaId));
258	            }
259	            if (dateRange?.from) q = q.gte('data_vencimento', format(dateRange.from, 'yyyy-MM-dd'));
260	            if (dateRange?.to) q = q.lte('data_vencimento', format(dateRange.to, 'yyyy-MM-dd'));
261	            return q;
262	        };
263	
264	        const data = await fetchAllRows(buildPendingQuery);
265	
266	        // Filter out parent records from calculation to avoid duplication or zero-value issues
267	        const effectiveData = data.filter((t: any) => !t.is_parent);
268	
269	        const totalPayable = roundMoney(effectiveData
270	            .filter(t => t.tipo === 'despesa' && t.status === 'pendente')
271	            .reduce((sum, t) => sum + Number(t.valor) + Number(t.valor_juros || 0), 0));
272	
273	        const totalReceivable = roundMoney(effectiveData
274	            .filter(t => t.tipo === 'receita' && t.status === 'pendente')
275	            .reduce((sum, t) => sum + Number(t.valor) + Number(t.valor_juros || 0), 0));
276	
277	        const totalOverdue = roundMoney(effectiveData
278	            .filter(t => t.status === 'pendente' && !!t.data_vencimento && t.data_vencimento < today)
279	            .reduce((sum, t) => sum + Number(t.valor) + Number(t.valor_juros || 0), 0));
280	
281	        const payableItems = effectiveData.filter(t => t.tipo === 'despesa' && t.status === 'pendente');
282	        const receivableItems = effectiveData.filter(t => t.tipo === 'receita' && t.status === 'pendente');
283	        const overdueItems = effectiveData.filter(t => t.status === 'pendente' && !!t.data_vencimento && t.data_vencimento < today);
284	        const countPayable = payableItems.length;
285	        const countReceivable = receivableItems.length;
286	        const countOverdue = overdueItems.length;
287	
288	        // Fetch paid despesas (filter by data_pagamento) and received receitas (filter by data_recebimento)
289	        // These use DIFFERENT date columns, so we split into two queries to avoid excluding receitas
290	        const buildPaidDespesasQuery = () => {
291	            let q = supabase
292	                .from('financial_transactions_unified' as any)
293	                .select('valor, tipo, is_parent, valor_juros')
294	                .eq('tipo', 'despesa')
295	                .eq('status', 'pago');
296	            if (effectiveLojaId && effectiveLojaId !== 'all') {
297	                q = q.eq('loja_id', parseInt(effectiveLojaId));
298	            }
299	            if (dateRange?.from) {
300	                q = q.gte('data_pagamento', format(dateRange.from, 'yyyy-MM-dd'));
301	            }
302	            if (dateRange?.to) {
303	                q = q.lte('data_pagamento', format(dateRange.to, 'yyyy-MM-dd'));
304	            }
305	            return q;
306	        };
307	
308	        const buildPaidReceitasQuery = () => {
309	            let q = supabase
310	                .from('financial_transactions_unified' as any)
311	                .select('valor, tipo, is_parent, valor_juros')
312	                .eq('tipo', 'receita')
313	                .eq('status', 'recebido');
314	            if (effectiveLojaId && effectiveLojaId !== 'all') {
315	                q = q.eq('loja_id', parseInt(effectiveLojaId));
316	            }
317	            if (dateRange?.from) {
318	                q = q.gte('data_recebimento', format(dateRange.from, 'yyyy-MM-dd'));
319	            }
320	            if (dateRange?.to) {
321	                q = q.lte('data_recebimento', format(dateRange.to, 'yyyy-MM-dd'));
322	            }
323	            return q;
324	        };
325	
326	        // Fetch both in parallel for performance
327	        const [paidDespesasRaw, paidReceitasRaw] = await Promise.all([
328	            fetchAllRows(buildPaidDespesasQuery),
329	            fetchAllRows(buildPaidReceitasQuery),
330	        ]);
331	
332	        const paidDespesas = paidDespesasRaw.filter((t: any) => !t.is_parent);
333	        const paidReceitas = paidReceitasRaw.filter((t: any) => !t.is_parent);
334	
335	        const totalPaid = roundMoney(paidDespesas.reduce((sum: number, t: any) => sum + Number(t.valor) + Number(t.valor_juros || 0), 0));
336	        const totalReceived = roundMoney(paidReceitas.reduce((sum: number, t: any) => sum + Number(t.valor) + Number(t.valor_juros || 0), 0));
337	        const totalPaidMonth = roundMoney(totalPaid + totalReceived);
338	        const countPaid = paidDespesas.length;
339	        const countReceived = paidReceitas.length;
340	
341	        // Count uncategorized NF-origin items
342	        let uncatQuery = supabase
343	            .from('contas_pagar_receber')
344	            .select('id', { count: 'exact', head: true })
345	            .eq('origem', 'nota_fiscal')
346	            .or('categoria.is.null,categoria.eq.outros,categoria.eq.,data_vencimento.is.null');
347	
348	        if (effectiveLojaId && effectiveLojaId !== 'all') {
349	            uncatQuery = uncatQuery.eq('loja_id', parseInt(effectiveLojaId));
350	        }
351	
352	        const { count: uncatCount } = await uncatQuery;
353	
354	        // Rich KPIs
355	        const totalInterestPaid = roundMoney(
356	            paidDespesas.reduce((sum: number, t: any) => sum + Number(t.valor_juros || 0), 0) +
357	            paidReceitas.reduce((sum: number, t: any) => sum + Number(t.valor_juros || 0), 0)
358	        );
359	
360	        const today7 = format(new Date(Date.now() + 7 * 86400000), 'yyyy-MM-dd');
361	        const dueSoonItems = effectiveData.filter(t => t.status === 'pendente' && t.tipo === 'despesa' && !!t.data_vencimento && t.data_vencimento >= today && t.data_vencimento <= today7);
362	        const dueSoon7d = roundMoney(dueSoonItems.reduce((sum, t) => sum + Number(t.valor), 0));
363	        const dueSoon7dCount = dueSoonItems.length;
364	
365	        const netBalance = roundMoney(totalReceivable - totalPayable);
366	
367	        // Average payment delay (dias entre vencimento e pagamento)
368	        let delaySum = 0;
369	        let delayCount = 0;
370	        paidDespesas.forEach((t: any) => {
371	            if (t.data_pagamento && t.data_vencimento) {
372	                const diff = (new Date(t.data_pagamento).getTime() - new Date(t.data_vencimento).getTime()) / 86400000;
373	                delaySum += diff;
374	                delayCount++;
375	            }
376	        });
377	        const avgPaymentDelay = delayCount > 0 ? Math.round(delaySum / delayCount) : 0;
378	
379	        setSummary({ totalPayable, totalReceivable, totalOverdue, totalPaidMonth, totalPaid, totalReceived, countPaid, countReceived, countPayable, countReceivable, countOverdue, uncategorizedCount: uncatCount || 0, dateContext, totalInterestPaid, dueSoon7d, dueSoon7dCount, netBalance, avgPaymentDelay });
380	    };
381	
382	    const createTransaction = async (newTransaction: Omit<FinancialTransaction, 'id' | 'created_at' | 'parcelas'>) => {
383	        try {
384	            // Strip parcelas from insert payload (they go in separate table)
385	            const { parcelas, ...insertPayload } = newTransaction as any;
386	            const { data, error } = await supabase
387	                .from('contas_pagar_receber')
388	                .insert(insertPayload)
389	                .select()
390	                .single();
391	
392	            if (error) throw error;
393	
394	            // Optimistic update if fits current page/filter, else just refresh
395	            setTransactions(prev => [data as FinancialTransaction, ...prev]);
396	            toast.success('Lançamento criado com sucesso!');
397	            calculateSummary(lastFetchParams.current.dateRange, lastFetchParams.current.lojaId);
398	            return data;
399	        } catch (error) {
400	            handleError(error, { domain: 'financeiro', operation: 'createTransaction', showToast: false });
401	            toast.error('Erro ao criar lançamento');
402	            throw error;
403	        }
404	    };
405	
406	    const createTransactionWithInstallments = async (
407	        newTransaction: Omit<FinancialTransaction, 'id' | 'created_at' | 'parcelas'>,
408	        numParcelas: number,
409	        firstDueDate: string,
410	        customInstallments?: Array<{ numero: number; valor: number; data_vencimento: string }>
411	    ) => {
412	        try {
413	            // 1. Create the parent transaction
414	            const parentData = await createTransaction({
415	                ...newTransaction,
416	                numero_parcelas: numParcelas,
417	                data_vencimento: firstDueDate,
418	            });
419	
420	            if (!parentData) throw new Error('Failed to create parent transaction');
421	
422	            const initialStatus = newTransaction.status || 'pendente';
423	            const initialPayDate = (newTransaction as any).data_pagamento || null;
424	
425	            let parcelas: Omit<Installment, 'id' | 'created_at'>[];
426	
427	            if (customInstallments && customInstallments.length === numParcelas) {
428	                // Use custom installments provided by the user
429	                parcelas = customInstallments.map(ci => ({
430	                    conta_id: parentData.id,
431	                    numero: ci.numero,
432	                    valor: Math.round(ci.valor * 100) / 100,
433	                    data_vencimento: ci.data_vencimento,
434	                    status: initialStatus,
435	                    data_pagamento: initialStatus === 'pago' ? initialPayDate : null,
436	                }));
437	            } else {
438	                // Auto-generate equal installments
439	                const totalCents = Math.round(Number(newTransaction.valor) * 100);
440	                const parcelaCents = Math.floor(totalCents / numParcelas);
441	                const valorParcela = parcelaCents / 100;
442	                const valorUltimaParcela = (totalCents - parcelaCents * (numParcelas - 1)) / 100;
443	
444	                parcelas = [];
445	                const startDate = new Date(firstDueDate + 'T12:00:00');
446	                for (let i = 0; i < numParcelas; i++) {
447	                    const dueDate = new Date(startDate);
448	                    dueDate.setMonth(dueDate.getMonth() + i);
449	                    parcelas.push({
450	                        conta_id: parentData.id,
451	                        numero: i + 1,
452	                        valor: i === numParcelas - 1 ? valorUltimaParcela : valorParcela,
453	                        data_vencimento: format(dueDate, 'yyyy-MM-dd'),
454	                        status: initialStatus,
455	                        data_pagamento: initialStatus === 'pago' ? initialPayDate : null,
456	                    });
457	                }
458	            }
459	
460	            const { error: parcelasError } = await supabase
461	                .from('contas_pagar_receber_parcelas')
462	                .insert(parcelas);
463	
464	            if (parcelasError) throw parcelasError;
465	
466	            toast.success(`${numParcelas} parcelas criadas com sucesso!`);
467	            calculateSummary(lastFetchParams.current.dateRange, lastFetchParams.current.lojaId);
468	            return parentData;
469	        } catch (error) {
470	            handleError(error, { domain: 'financeiro', operation: 'createInstallments', showToast: false });
471	            toast.error('Erro ao criar parcelas');
472	            throw error;
473	        }
474	    };
475	
476	    const updateTransactionWithInstallments = async (
477	        contaId: string,
478	        numParcelas: number,
479	        valorTotal: number,
480	        firstDueDate: string
481	    ) => {
482	        try {
483	            const valorParcela = Math.round((Number(valorTotal) / numParcelas) * 100) / 100;
484	            const valorUltimaParcela = Number(valorTotal) - (valorParcela * (numParcelas - 1));
485	
486	            // 1. Update parent transaction
487	            const { error: updateError } = await supabase
488	                .from('contas_pagar_receber')
489	                .update({
490	                    valor: valorTotal,
491	                    numero_parcelas: numParcelas,
492	                    data_vencimento: firstDueDate,
493	                })
494	                .eq('id', contaId);
495	
496	            if (updateError) throw updateError;
497	
498	            // Fetch parent status to apply to new installments
499	            const { data: parentData } = await supabase
500	                .from('contas_pagar_receber')
501	                .select('status, data_pagamento')
502	                .eq('id', contaId)
503	                .single();
504	
505	            const parentStatus = parentData?.status || 'pendente';
506	            const parentPayDate = parentData?.data_pagamento || null;
507	
508	            // 2. Delete existing installments
509	            const { error: deleteError } = await supabase
510	                .from('contas_pagar_receber_parcelas')
511	                .delete()
512	                .eq('conta_id', contaId);
513	
514	            if (deleteError) throw deleteError;
515	
516	            // 3. Create new installments
517	            const parcelas: Omit<Installment, 'id' | 'created_at'>[] = [];
518	            const startDate = new Date(firstDueDate + 'T12:00:00');
519	
520	            for (let i = 0; i < numParcelas; i++) {
521	                const dueDate = new Date(startDate);
522	                dueDate.setMonth(dueDate.getMonth() + i);
523	
524	                parcelas.push({
525	                    conta_id: contaId,
526	                    numero: i + 1,
527	                    valor: i === numParcelas - 1 ? valorUltimaParcela : valorParcela,
528	                    data_vencimento: format(dueDate, 'yyyy-MM-dd'),
529	                    status: parentStatus,
530	                    data_pagamento: parentStatus === 'pago' ? parentPayDate : null
531	                });
532	            }
533	
534	            const { error: insertError } = await supabase
535	                .from('contas_pagar_receber_parcelas')
536	                .insert(parcelas);
537	
538	            if (insertError) throw insertError;
539	
540	            toast.success('Parcelamento atualizado com sucesso!');
541	            // We do NOT update local state here to avoid optimistic duplication.
542	            // The component must trigger a refresh.
543	            calculateSummary(lastFetchParams.current.dateRange, lastFetchParams.current.lojaId);
544	        } catch (error) {
545	            handleError(error, { domain: 'financeiro', operation: 'updateInstallments', showToast: false });
546	            toast.error('Erro ao atualizar parcelamento');
547	            throw error;
548	        }
549	    };
550	
551	    const fetchInstallments = async (contaId: string): Promise<Installment[]> => {
552	        const { data, error } = await supabase
553	            .from('contas_pagar_receber_parcelas')
554	            .select('*')
555	            .eq('conta_id', contaId)
