683	    // ── Auto-Accounting: generate account_move when marking paid ──
684	    const generateAccountingEntry = async (transaction: FinancialTransaction, payDate: string) => {
685	        try {
686	            // 1. Find the best journal (first bank journal, fallback to cash, then general)
687	            const { data: journals } = await supabase
688	                .from('account_journals')
689	                .select('id, name, type, default_account_id')
690	                .in('type', ['bank', 'cash', 'general'])
691	                .order('type');
692	
693	            if (!journals || journals.length === 0) {
694	                wideWarn('financeiro.accounting_no_journals', { domain: 'financeiro', operation: 'generateAccountingEntry', transactionId: transaction.id });
695	                return;
696	            }
697	
698	            const journal = journals.find(j => j.type === 'bank')
699	                || journals.find(j => j.type === 'cash')
700	                || journals[0];
701	
702	            // 2. Determine accounts: bank/cash account vs expense/revenue account
703	            const bankAccountId = journal.default_account_id;
704	            if (!bankAccountId) {
705	                wideWarn('financeiro.accounting_no_default_account', { domain: 'financeiro', operation: 'generateAccountingEntry', journalId: journal.id, journalName: journal.name });
706	                return;
707	            }
708	
709	            // Try to find the counter-account from DRE subconta
710	            let counterAccountId: number | null = null;
711	            if (transaction.categoria) {
712	                const matchCat = categories.find(c =>
713	                    c.name.toLowerCase() === transaction.categoria?.toLowerCase()
714	                );
715	                if (matchCat?.default_account_id) {
716	                    counterAccountId = matchCat.default_account_id;
717	                }
718	            }
719	
720	            // Fallback: use a generic expense/revenue account
721	            if (!counterAccountId) {
722	                const accountType = transaction.tipo === 'despesa' ? 'expense' : 'income';
723	                const { data: fallbackAccounts } = await supabase
724	                    .from('account_accounts')
725	                    .select('id')
726	                    .eq('account_type', accountType)
727	                    .limit(1);
728	                counterAccountId = fallbackAccounts?.[0]?.id || null;
729	            }
730	
731	            if (!counterAccountId) {
732	                wideWarn('financeiro.accounting_no_counter_account', { domain: 'financeiro', operation: 'generateAccountingEntry', transactionId: transaction.id, tipo: transaction.tipo });
733	                return;
734	            }
735	
736	            // 3. Determine debit/credit:
737	            // Despesa (A Pagar paid): debit=expense, credit=bank
738	            // Receita (A Receber paid): debit=bank, credit=revenue
739	            const isDespesa = transaction.tipo === 'despesa';
740	            const debitAccountId = isDespesa ? counterAccountId : bankAccountId;
741	            const creditAccountId = isDespesa ? bankAccountId : counterAccountId;
742	
743	            // 4. Create account_move
744	            const { data: moveData, error: moveErr } = await supabase
745	                .from('account_moves')
746	                .insert({
747	                    journal_id: journal.id,
748	                    date: payDate,
