756	            if (moveErr) throw moveErr;
757	
758	            // 5. Create move lines (debit + credit)
759	            const { error: linesErr } = await supabase
760	                .from('account_move_lines')
761	                .insert([
762	                    {
763	                        move_id: moveData.id,
764	                        account_id: debitAccountId,
765	                        name: transaction.descricao,
766	                        debit: transaction.valor,
767	                        credit: 0,
768	                        date: payDate,
769	                        partner_name: (transaction as any).fornecedor_nome || null,
770	                    },
771	                    {
772	                        move_id: moveData.id,
