791	    const updateStatus = async (id: string, status: FinancialTransaction['status'], paymentDate?: string) => {
792	        try {
793	            const updates: any = { status };
794	            const payDate = paymentDate || todayLocalISO();
795	            if (status === 'pago') {
796	                updates.data_pagamento = payDate;
797	            } else if (status === 'recebido') {
