799	            } else if (status === 'pendente' || status === 'cancelado' || status === 'atrasado') {
800	                updates.data_pagamento = null;
801	                updates.data_recebimento = null;
802	            }
803	
804	            const { error } = await supabase
805	                .from('contas_pagar_receber')
