68	export function useCustosFixos(mesReferencia?: Date) {
69	  const [data, setData] = useState<CustoFixoRow[]>([]);
70	  const [loading, setLoading] = useState(true);
71	  const [saving, setSaving] = useState(false);
72	  const { toast } = useToast();
73	
74	  const mesRef = format(
75	    startOfMonth(mesReferencia || new Date()),
76	    'yyyy-MM-dd',
77	  );
78	
79	  const fetchData = useCallback(async () => {
80	    setLoading(true);
81	    const { data: rows, error } = await supabase
82	      .from('custos_fixos')
83	      .select('*')
84	      .eq('mes_referencia', mesRef)
85	      .order('grupo')
86	      .order('item');
87	
88	    if (error) {
89	      toast({ title: 'Erro ao carregar custos fixos', description: error.message, variant: 'destructive' });
90	    } else {
91	      setData((rows as CustoFixoRow[]) || []);
92	    }
93	    setLoading(false);
94	  }, [mesRef]);
95	
96	  useEffect(() => {
97	    fetchData();
98	  }, [fetchData]);
99	
100	  const getValue = (lojaId: number, grupo: string, item: string): number => {
101	    const row = data.find(
102	      (r) => r.loja_id === lojaId && r.grupo === grupo && r.item === item,
103	    );
104	    return row?.valor ?? 0;
105	  };
106	
107	  const getGroupTotal = (lojaId: number, grupo: string): number => {
108	    return roundMoney(data
109	      .filter((r) => r.loja_id === lojaId && r.grupo === grupo)
110	      .reduce((sum, r) => sum + Number(r.valor), 0));
111	  };
112	
113	  const getStoreTotal = (lojaId: number): number => {
114	    return roundMoney(data
115	      .filter((r) => r.loja_id === lojaId)
116	      .reduce((sum, r) => sum + Number(r.valor), 0));
117	  };
118	
119	  const getGrandTotal = (): number => {
120	    return roundMoney(data.reduce((sum, r) => sum + Number(r.valor), 0));
121	  };
122	
123	  const upsertValue = async (
124	    lojaId: number,
125	    grupo: string,
126	    item: string,
127	    valor: number,
128	  ) => {
129	    setSaving(true);
130	    const { error } = await supabase
131	      .from('custos_fixos')
132	      .upsert(
133	        {
134	          loja_id: lojaId,
135	          grupo,
136	          item,
137	          valor,
138	          mes_referencia: mesRef,
139	        },
140	        { onConflict: 'loja_id,grupo,item,mes_referencia' },
141	      );
142	
143	    if (error) {
144	      toast({ title: 'Erro ao salvar', description: error.message, variant: 'destructive' });
145	    } else {
146	      // Update local state optimistically
147	      setData((prev) => {
148	        const idx = prev.findIndex(
149	          (r) => r.loja_id === lojaId && r.grupo === grupo && r.item === item,
150	        );
151	        if (idx >= 0) {
152	          const next = [...prev];
153	          next[idx] = { ...next[idx], valor };
154	          return next;
155	        }
156	        return [...prev, { loja_id: lojaId, grupo, item, valor, mes_referencia: mesRef }];
157	      });
158	    }
159	    setSaving(false);
160	  };
161	
162	  const copyFromPreviousMonth = async () => {
163	    const prevMonth = new Date(mesReferencia || new Date());
164	    prevMonth.setMonth(prevMonth.getMonth() - 1);
165	    const prevRef = format(startOfMonth(prevMonth), 'yyyy-MM-dd');
166	
167	    setSaving(true);
168	    const { data: prevData, error } = await supabase
169	      .from('custos_fixos')
170	      .select('*')
171	      .eq('mes_referencia', prevRef);
172	
173	    if (error || !prevData?.length) {
174	      toast({
175	        title: 'Nenhum dado encontrado',
176	        description: 'Não há custos fixos no mês anterior para copiar.',
177	        variant: 'destructive',
178	      });
179	      setSaving(false);
180	      return;
181	    }
182	
183	    const rows = (prevData as CustoFixoRow[]).map((r) => ({
184	      loja_id: r.loja_id,
185	      grupo: r.grupo,
186	      item: r.item,
187	      valor: r.valor,
188	      mes_referencia: mesRef,
189	    }));
190	
191	    const { error: upsertError } = await supabase
192	      .from('custos_fixos')
193	      .upsert(rows, { onConflict: 'loja_id,grupo,item,mes_referencia' });
194	
195	    if (upsertError) {
196	      toast({ title: 'Erro ao copiar', description: upsertError.message, variant: 'destructive' });
197	    } else {
198	      toast({ title: 'Custos copiados', description: 'Valores do mês anterior copiados com sucesso.' });
199	      fetchData();
200	    }
201	    setSaving(false);
202	  };
203	
204	  return {
205	    data,
206	    loading,
207	    saving,
208	    getValue,
209	    getGroupTotal,
210	    getStoreTotal,
211	    getGrandTotal,
212	    upsertValue,
213	    copyFromPreviousMonth,
214	    refresh: fetchData,
215	  };
216	}
